INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(46961, 'Zechariah 7:5', 'Zechariah', 7, 5, '”د دې مُلک د ټولو خلقو نه او اِمامانو نه پوښتنه وکړه، کله چې تاسو روژه نيوله او ماتم مو په پينځمه او اوومه مياشت کښې د تېرو اويا کالو راسې کولو، آيا دا روژې په حقيقت تاسو زما دپاره نيولې؟', '”د دې ملک د تولو خلقو نه او امامانو نه پوشتنه وکره، کله چې تاسو روژه نیوله او ماتم مو په پینجمه او اوومه میاشت کشې د تېرو اویا کالو راسې کولو، ایا دا روژې په حقیقت تاسو زما دپاره نیولې؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Zechariah_7_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46962, 'Zechariah 7:6', 'Zechariah', 7, 6, 'او کله چې تاسو خوراک څښاک کولو، آيا دا تاسو د ځان دپاره نۀ کولو؟', 'او کله چې تاسو خوراک چشاک کولو، ایا دا تاسو د جان دپاره نۀ کولو؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Zechariah_7_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46963, 'Zechariah 7:7', 'Zechariah', 7, 7, 'آيا دا هغه کلام نۀ دے چې ما مالِک خُدائ فرمائيلى وُو د وړومبيو پېغمبرانو په ذريعه کله چې په يروشلم او د دې نه ګېرچاپېره کلو کښې سکون او برکت وو، او نجب او د مغربى غرونو لمنې ښۀ آبادې وې؟“', 'ایا دا هغه کلام نۀ دے چې ما مالک خدای فرماییلی وو د ورومبیو پېغمبرانو په ذریعه کله چې په یروشلم او د دې نه ګېرچاپېره کلو کشې سکون او برکت وو، او نجب او د مغربی غرونو لمنې شۀ ابادې وې؟“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Zechariah_7_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46964, 'Zechariah 7:8', 'Zechariah', 7, 8, 'او د مالِک خُدائ ربُ الافواج کلام بيا په زکرياه نازل شو،', 'او د مالک خدای رب الافواج کلام بیا په زکریاه نازل شو،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Zechariah_7_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46965, 'Zechariah 7:9', 'Zechariah', 7, 9, '”دا مالِک خُدائ ربُ الافواج فرمائى، په رښتيا سره اِنصاف کوئ، يو بل سره رحم او مينه کوئ.', '”دا مالک خدای رب الافواج فرمایی، په رشتیا سره انصاف کوی، یو بل سره رحم او مینه کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Zechariah_7_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46966, 'Zechariah 7:10', 'Zechariah', 7, 10, 'په کونډو، يتيمانو، په پردو او غريبانانو ظلم زياتے مۀ کوئ. په خپلو زړونو کښې يو بل ته شېطانى سوچونه مۀ کوئ.', 'په کوندو، یتیمانو، په پردو او غریبانانو ظلم زیاتے مۀ کوی. په خپلو زرونو کشې یو بل ته شېطانی سوچونه مۀ کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Zechariah_7_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46967, 'Zechariah 7:11', 'Zechariah', 7, 11, 'خو هغوئ په دې غور کولو نه اِنکار وکړو، او په سرکشۍ سره يې ورته شا کړه او خپل غوږونه يې بند کړل.', 'خو هغوی په دې غور کولو نه انکار وکرو، او په سرکشی سره یې ورته شا کره او خپل غوزونه یې بند کرل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Zechariah_7_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46968, 'Zechariah 7:12', 'Zechariah', 7, 12, 'هغوئ خپل زړونه لکه د هيرې سخت کاڼى په شان سخت کړل او هغوئ هغه حکمونو يا تعليماتو ته توجو نۀ ورکوله چې مالِک خُدائ ربُ الافواج د خپل روح نه د پخوانو پېغمبرانو په ذريعه رالېږلى وُو، نو په دې وجه مالِک خُدائ ربُ الافواج سخت په قهر شو.', 'هغوی خپل زرونه لکه د هیرې سخت کانی په شان سخت کرل او هغوی هغه حکمونو یا تعلیماتو ته توجو نۀ ورکوله چې مالک خدای رب الافواج د خپل روح نه د پخوانو پېغمبرانو په ذریعه رالېزلی وو، نو په دې وجه مالک خدای رب الافواج سخت په قهر شو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Zechariah_7_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46969, 'Zechariah 7:13', 'Zechariah', 7, 13, 'کله چې ما ورته آواز وکړو، نو هغوئ نۀ اورېدلو، او نو اوس کله چې هغوئ آواز وکړى، نو زۀ به يې نۀ اورم، مالِک خُدائ ربُ الافواج فرمائى.', 'کله چې ما ورته اواز وکرو، نو هغوی نۀ اورېدلو، او نو اوس کله چې هغوی اواز وکری، نو زۀ به یې نۀ اورم، مالک خدای رب الافواج فرمایی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Zechariah_7_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46970, 'Zechariah 7:14', 'Zechariah', 7, 14, 'ما هغوئ د طوفان په ذريعه په لرى قومونو کښې خوارۀ وارۀ کړل، چرته چې هغوئ لکه د پردو په شان اوسېدل. د هغوئ مُلک وران ويجاړ پروت وُو او د هغوئ نه پس ورته څوک نۀ شو راتلے. نو دغه شان د هغوئ خپل ښکلے مُلک په صحرا بدل شو.“', 'ما هغوی د طوفان په ذریعه په لری قومونو کشې خوارۀ وارۀ کرل، چرته چې هغوی لکه د پردو په شان اوسېدل. د هغوی ملک وران ویجار پروت وو او د هغوی نه پس ورته چوک نۀ شو راتلے. نو دغه شان د هغوی خپل شکلے ملک په صحرا بدل شو.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Zechariah_7_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46971, 'Proverbs 8:1', 'Proverbs', 8, 1, 'حکمت د یوې هوښیارې ښځې په څېر نارې وهي او پوهه په لوړ اواز خپل غږ پورته کوي.', 'حکمت د یوې هوشیارې شجې په چېر نارې وهی او پوهه په لور اواز خپل غز پورته کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs008_verse_001.mp3', 'https://drive.google.com/file/d/1K0oobh-VHCh_ibzOXtdjI5yhLcur0ovb/preview', 1761237844, 1761237844),
(46972, 'Proverbs 8:2', 'Proverbs', 8, 2, 'هغه د لارې په غاړه په لوړو ځایونو ولاړه وي او د څلور لارو په سر ودریږي.', 'هغه د لارې په غاره په لورو جایونو ولاره وی او د چلور لارو په سر ودریزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs008_verse_002.mp3', 'https://drive.google.com/file/d/1iOrVluqpoIWCeni-GKZZN_ve2QoUB7BE/preview', 1761237844, 1761237844),
(46973, 'Proverbs 8:3', 'Proverbs', 8, 3, 'هغه د ښار د دروازو دننه د تګ راتګ د لارو په خوا کې نارې وهي:', 'هغه د شار د دروازو دننه د تګ راتګ د لارو په خوا کې نارې وهی:', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs008_verse_003.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1Kn3tz0L-tRlTibsQjT508vC9yE6grpV8&export=download', 1761237844, 1761237844),
(46974, 'Proverbs 8:4', 'Proverbs', 8, 4, '«ای سړیو! زه په تاسو ټولو ته غږ کوم او په تاسو ټولو باندې اواز کوم.', '«ای سریو! زه په تاسو تولو ته غز کوم او په تاسو تولو باندې اواز کوم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs008_verse_004.mp3', 'https://drive.google.com/file/d/1dgueuZ9ToSOW_l9dZmL1OZVMwfvDBn0T/preview', 1761237844, 1761237844),
(46975, 'Proverbs 8:5', 'Proverbs', 8, 5, 'ای ساده خلکو! په خپل ځان کې ځیرکتیا پیدا کړئ! ای کم‌عقلانو! د ښو او بدو ترمنځ فرق وکړئ!', 'ای ساده خلکو! په خپل جان کې جیرکتیا پیدا کری! ای کم‌عقلانو! د شو او بدو ترمنج فرق وکری!', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs008_verse_005.mp3', 'https://drive.google.com/file/d/1xuMsFyGXYOSeTH3qwENLhZ4AjoSkxG0d/preview', 1761237844, 1761237844),
(46976, 'Proverbs 8:6', 'Proverbs', 8, 6, 'غوږ ونیسئ! زه ستاسو دپاره ښې خبرې لرم چې په رښتینې ژبه به یې درته بیان کړم.', 'غوز ونیسی! زه ستاسو دپاره شې خبرې لرم چې په رشتینې ژبه به یې درته بیان کرم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs008_verse_006.mp3', 'https://drive.google.com/file/d/1Hh2_vbe9sD46PlH_V9AfuV2lW_TnxvdQ/preview', 1761237844, 1761237844),
(46977, 'Proverbs 8:7', 'Proverbs', 8, 7, 'زه چې څه په خوله وایم، هغه رښتیا دي او ژبه مې له بدو خبرو نه کرکه کوي.', 'زه چې چه په خوله وایم، هغه رشتیا دی او ژبه مې له بدو خبرو نه کرکه کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs008_verse_007.mp3', 'https://drive.google.com/file/d/1nl57v_K2xAAkyGhAXEdXVuTIHEBePfv_/preview', 1761237844, 1761237844),
(46978, 'Proverbs 8:8', 'Proverbs', 8, 8, 'د خولې ټولې خبرې مې سمې دي یوه هم په کې کږه او غولوونکې نه ده', 'د خولې تولې خبرې مې سمې دی یوه هم په کې کزه او غولوونکې نه ده', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs008_verse_008.mp3', 'https://drive.google.com/file/d/1hXSUZL2A-IZ69JvvTL-igcdtfExpicY5/preview', 1761237844, 1761237844),
(46979, 'Proverbs 8:9', 'Proverbs', 8, 9, 'چې عقلمن انسان ته ټولې روښانه دي څوک چې علم لري نو پوهیږي چې دا خبرې سمې دي.', 'چې عقلمن انسان ته تولې روشانه دی چوک چې علم لری نو پوهیزی چې دا خبرې سمې دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs008_verse_009.mp3', 'https://drive.google.com/file/d/11yXCD4yr4lDoVodMoANxL6xfPlsBmP8V/preview', 1761237844, 1761237844),
(46980, 'Proverbs 8:10', 'Proverbs', 8, 10, 'د سپینو زرو په ځای زما نصیحت غوره کړئ او د سوچه سرو زرو په ځای علم حاصل کړئ', 'د سپینو زرو په جای زما نصیحت غوره کری او د سوچه سرو زرو په جای علم حاصل کری', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs008_verse_010.mp3', 'https://drive.google.com/file/d/1OVpG38SyDsyC_jAFP-ZNxqP5Qk2SrAuV/preview', 1761237844, 1761237844),
(46981, 'Proverbs 8:11', 'Proverbs', 8, 11, 'ځکه حکمت د لعلونو نه ډېر قیمتي دی چې له ارزښت سره یې ستا د خوښې هېڅ شی برابر نه دی.', 'جکه حکمت د لعلونو نه دېر قیمتی دی چې له ارزشت سره یې ستا د خوشې هېچ شی برابر نه دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs008_verse_011.mp3', 'https://drive.google.com/file/d/1GdRYz37LTAj6WTUW8tQDRbZBwtqj9nif/preview', 1761237844, 1761237844),
(46982, 'Proverbs 8:12', 'Proverbs', 8, 12, 'زه حکمت یم او له ځیرکتیا سره یو ځای اوسېږم او علم او لیاقت تر‌لاسه کوم.', 'زه حکمت یم او له جیرکتیا سره یو جای اوسېزم او علم او لیاقت تر‌لاسه کوم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs008_verse_012.mp3', 'https://drive.google.com/file/d/1I9u4uGtbUoHptP0YCWAxtkXbEfE3wsSH/preview', 1761237844, 1761237844),
(46983, 'Proverbs 8:13', 'Proverbs', 8, 13, 'له څښتن څخه وېره له شرارت نه نفرت کول دي نو ځکه له کبر، غرور، بدۍ او کږو خبرو نه کرکه کوم.', 'له چشتن چخه وېره له شرارت نه نفرت کول دی نو جکه له کبر، غرور، بدی او کزو خبرو نه کرکه کوم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs008_verse_013.mp3', 'https://drive.google.com/file/d/1kjhNGh23PSEgZjKw4MGXqyEyKZgqzIO5/preview', 1761237844, 1761237844),
(46984, 'Proverbs 8:14', 'Proverbs', 8, 14, 'مشوره او حکمت زما کار دی زه عقلمن یم او زما سره قدرت دی.', 'مشوره او حکمت زما کار دی زه عقلمن یم او زما سره قدرت دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs008_verse_014.mp3', 'https://drive.google.com/file/d/14aFO7CvKrtNwgJIhnbgKd5hQUxfix3Ru/preview', 1761237844, 1761237844),
(46985, 'Proverbs 8:15', 'Proverbs', 8, 15, 'پاچاهان زما په مرسته پاچاهي کوي او حکمرانان د انصاف پرېکړې کوي.', 'پاچاهان زما په مرسته پاچاهی کوی او حکمرانان د انصاف پرېکرې کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs008_verse_015.mp3', 'https://drive.google.com/file/d/1kHzFkhyxACB7KqbHrpLFCbgp63lKrU5H/preview', 1761237844, 1761237844),
(46986, 'Proverbs 8:16', 'Proverbs', 8, 16, 'شهزادګان زما په مرسته حکومت کوي واکداران او ټول عادل قاضیان پرېکړې کوي.', 'شهزادګان زما په مرسته حکومت کوی واکداران او تول عادل قاضیان پرېکرې کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs008_verse_016.mp3', 'https://drive.google.com/file/d/1pp6jjrgYvPahcJxfoHsPsgwWtRXrtLyt/preview', 1761237844, 1761237844),
(46987, 'Proverbs 8:17', 'Proverbs', 8, 17, 'زه له خپلو مینوالو سره مینه کوم څوک چې ما لټوي نو ما پیدا کوي.', 'زه له خپلو مینوالو سره مینه کوم چوک چې ما لتوی نو ما پیدا کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs008_verse_017.mp3', 'https://drive.google.com/file/d/1b7bAz-ARyzVJY_GqyYvqycs2Ve11bDVO/preview', 1761237844, 1761237844),
(46988, 'Proverbs 8:18', 'Proverbs', 8, 18, 'دولت او عزت زما سره دی عدالت او تلپاتې شتمني زما ده.', 'دولت او عزت زما سره دی عدالت او تلپاتې شتمنی زما ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs008_verse_018.mp3', 'https://drive.google.com/file/d/1dUBNT9pRdIMhDHo7JGTxJGIYOahkeCXc/preview', 1761237844, 1761237844),
(46989, 'Proverbs 8:19', 'Proverbs', 8, 19, 'زه د خالصو سرو زرو نه غوره مېوه ورکوم چې حاصل یې له سوچه سپینو زرو نه بهتر دی.', 'زه د خالصو سرو زرو نه غوره مېوه ورکوم چې حاصل یې له سوچه سپینو زرو نه بهتر دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs008_verse_019.mp3', 'https://drive.google.com/file/d/1OT7MMbdKJMFchBhwwptt8pjFMWAFXH3H/preview', 1761237844, 1761237844),
